from collections import deque

def flood_fill_reachable(grid, row_index=None, include_row=None):
    """Returns reachable 1s from a specified set of starting positions"""
    rows = len(grid)
    cols = len(grid[0])
    reachable = set()
    queue = deque()

    if row_index is None:
        # Use include_row as starting positions
        for r, c in include_row:
            queue.append((r, c))
            reachable.add((r, c))
    elif include_row is not None:
        # Start from all 1s in row_index
        for c in range(cols):
            if grid[row_index][c] == 1:
                queue.append((row_index, c))
                reachable.add((row_index, c))
    elif include_row is None:
        # Start from row_index
        for c in range(cols):
            if grid[row_index][c] == 1:
                queue.append((row_index, c))
                reachable.add((row_index, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if (nr, nc) not in reachable and 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                queue.append((nr, nc))
                reachable.add((nr, nc))

    return reachable

